k as materialized (
  select ci.title, ci.image_url, ci.tags::text as tags, ci.source_id,
         (ci.embedding <=> q.v) as dist,
         rank() over (order by ci.embedding <=> q.v) as rk
  from public.catalog_items ci, q
  where ci.embedding is not null
)
select k.rk as posicao, k.title, s.name as fonte,
       round((1 - k.dist)::numeric, 4) as sim,
       (select round((1 - k2.dist)::numeric, 4) from k k2 where k2.rk = 100) as corte_100,
       (select count(*) from k k3 where k3.title ilike 'MN%') as total_mn,
       k.tags, k.image_url
from k join public.sources s on s.id = k.source_id
where k.title ilike 'MN%'
order by k.rk
limit 15;
